            "Regional Isolation Builder implementa desde ese handoff; Residency Evidence Inspector lee contract y builder handoffs para verificar region proof, wrong-region write/read/export, processor mismatch, stale policy, keys, failover, migration, access/export/audit/trace y monitoring; "
            "GateKeeper combina todo y fail closed ante UI-region-only, env-var-only, tenant-field-only, one-routed-request-only, docs-only DPA o falta de negativos / egress alerts / key-region proof; "
