            "Regional Isolation Builder implements only after that contract handoff; Residency Evidence Inspector reads contract and builder handoffs to verify region proof, wrong-region write/read/export, processor mismatch, stale policy, key, failover, migration, access/export/audit/trace, and monitoring; "
            "GateKeeper combines all handoffs and evidence_query and fails closed on UI-region-only, env-var-only, tenant-field-only, one-routed-request-only, docs-only DPA, or missing wrong-region negatives / egress alerts / key-region proof; "
            "Weak, Unproven, Blocking, and fake-done gaps must surface before closure; residency proof beats pragmatic progress, so a region selector or one routed request cannot substitute real regional proof."
