            "KYC/AML Builder implementa desde ese handoff; Screening Evidence Inspector y Financial Controls Inspector leen contract y builder handoffs en el mismo parallel_group, "
            "refutando screening/provider/webhook y payout/ledger/privacy/audit/monitoring; GateKeeper combina todo y fail closed ante sandbox-only, UI-only, provider-status-only, happy-path webhook, manual review débil o falta de sanctions negatives / payout ledger."
