            "This marketplace seller onboarding KYC/KYB and AML sanctions screening task needs multi-round Loopora governance because provider contracts, sanctions / PEP / watchlist negatives, document OCR/liveness, manual review, appeal/resubmission, rescreening, webhook replay/order/idempotency, payout hold/release ledger, region retention, privacy redaction, audit reasons, monitoring, and local governance need later rounds to create new evidence and staged handoffs; provider-approved, UI-verified, provider-status-only, or happy-path webhook evidence is too thin. "
            "The spec freezes compliance success semantics, fake-done risks, and evidence preferences; roles separate read-only compliance contract, implementation, screening evidence inspection, financial controls inspection, and GateKeeper judgment; workflow fails closed on sandbox-approved-only, UI-verified-only, provider-status-only, happy-path webhook, weak manual-review proof, missing sanctions negatives, or missing payout ledger proof before closure."
