            "KYC/AML Builder implements only after that handoff; Screening Evidence Inspector and Financial Controls Inspector read contract plus builder handoffs in one parallel_group, "
            "separately refuting screening / document / provider / webhook and payout / ledger / retention / privacy / audit / monitoring claims; GateKeeper combines all handoffs and evidence_query and fails closed on sandbox-approved-only, UI-verified-only, provider-status-only, happy-path webhook, weak manual review, missing sanctions negatives, or missing payout ledger proof."
