def _append_rag_long_chain_spec_notes(
    bundle: dict,
    *,
    prefers_chinese: bool,
    task: str,
    display_language: str = "",
) -> None:
    if not _is_rag_long_chain_task(task):
        return
    markdown = str(bundle.get("spec", {}).get("markdown") or "")
    if "# Long-Chain Workflow Notes" in markdown:
        return
    if prefers_chinese:
        notes = """

# Long-Chain Workflow Notes
- 这次 RAG 任务要拆成 contract inspection、corpus ingestion、retrieval ACL、answer/tool gating、evaluation inspection、evidence hardening 和 GateKeeper，而不是一个通用 Builder 一次性推进。
- Corpus Ingestion Builder 只留下 document version、source chunk 和 citation/source-span artifact；Retrieval ACL Builder 只证明 permission-filtered retrieval 与 tenant filtering；Answer Tooling Builder 只证明 grounded answer、tool allowlist、redaction 和 fallback。
- RAG Evaluation Inspector 必须读取 ingestion、retrieval 和 answer handoff，验证 source span、prompt-injection negative docs、unauthorized tool-call blocking、PII leak tests、eval set、human review 和 monitoring。
- GateKeeper 必须读取 contract、evaluation 和 hardening handoff，并从 evidence_query 裁决 RAG grounding、tool safety、permission、privacy、eval-set、human-review、monitoring 和 local-governance；demo-only 或 UI-citation-only 证据必须 fail closed。
"""
    elif str(display_language or "").strip().lower() == "es":
        notes = """

# Long-Chain Workflow Notes
- Esta tarea RAG se divide en contract inspection, corpus ingestion, retrieval ACL, answer/tool gating, evaluation inspection, evidence hardening y GateKeeper, no en un Builder genérico.
- Corpus Ingestion Builder deja document versions, source chunks y citation/source-span artifacts; Retrieval ACL Builder prueba permission-filtered retrieval y tenant filtering; Answer Tooling Builder prueba grounded answers, tool allowlist, redaction y fallback.
- RAG Evaluation Inspector lee handoffs de ingestion, retrieval y answer para verificar source spans, documentos negativos de prompt injection, bloqueo de tool calls no autorizados, PII leak tests, eval set, human review y monitoring.
- GateKeeper lee contract, evaluation y hardening handoffs y decide desde evidence_query sobre RAG grounding, tool safety, permission, privacy, eval-set, human-review, monitoring y local-governance; demo-only o UI-citation-only debe fail closed.
"""
    else:
        notes = """

# Long-Chain Workflow Notes
- This RAG task splits into contract inspection, corpus ingestion, retrieval ACL, answer/tool gating, evaluation inspection, evidence hardening, and GateKeeper instead of one generic Builder pass.
- Corpus Ingestion Builder leaves document version, source chunk, and citation/source-span artifacts; Retrieval ACL Builder proves permission-filtered retrieval and tenant filtering; Answer Tooling Builder proves grounded answers, tool allowlist, redaction, and fallback.
- RAG Evaluation Inspector reads ingestion, retrieval, and answer handoffs to verify source spans, negative prompt-injection docs, unauthorized tool-call blocking, PII leak tests, eval set, human review, and monitoring.
- GateKeeper reads contract, evaluation, and hardening handoffs and judges RAG grounding, tool safety, permission, privacy, eval-set, human-review, monitoring, and local-governance through evidence_query; demo-only or UI-citation-only evidence must fail closed.
"""
    bundle["spec"]["markdown"] = markdown.rstrip() + notes


def _is_rag_long_chain_task(task: str) -> bool:
    text = str(task or "")
    if not re.search(r"\bRAG\b|retrieval|知识库|检索增强", text, re.IGNORECASE):
        return False
    phase_markers = (
        r"\bingestion\b|文档\s*ingestion|语料|corpus",
        r"retrieval\s*ACL|permission-filtered\s+retrieval|tenant\s+filtering|检索权限|租户过滤",
        r"answer/tool|tool\s+gating|tool\s+allowlist|答案.*工具|工具.*白名单",
        r"\beval(?:uation)?\b|eval\s*set|human\s+review|评估|评测集|人工评审",
        r"monitoring|regression\s+monitoring|监控|告警",
        r"evidence\s+hardening|hardening|证据.*修复|补证据",
    )
    matched = sum(1 for pattern in phase_markers if re.search(pattern, text, re.IGNORECASE))
    if matched >= 4 and re.search(r"独立阶段|阶段|long[- ]?chain|长链|phase|multiple\s+evidence\s+rounds", text, re.IGNORECASE):
        return True
    success_markers = (
        r"grounded|source\s+chunks?|source\s+span|citation|document\s+version|答案.*来源|文档版本|引用",
        r"retrieval\s*ACL|tenant\s+filtering|permission-filtered|检索权限|租户过滤|权限过滤",
        r"prompt[- ]?injection|system\s+prompt|系统提示词|提示词注入",
        r"tool\s+allowlist|unauthorized\s+tool|tool[- ]?call|工具.*白名单|未授权\s*tool",
        r"PII|secrets?|redaction|脱敏|敏感|隐私",
        r"hallucination|fallback|handoff|no[- ]?answer|幻觉|兜底|转人工|无法回答",
        r"eval\s*set|golden\s+Q&A|faithfulness|citation\s+precision|top[- ]?k|human\s+review|评测集|人工评审",
        r"demo\s+question|plausible|embedding\s+search|UI\s+citations?|单个\s*demo|看起来合理|UI.*citation",
    )
    return sum(1 for pattern in success_markers if re.search(pattern, text, re.IGNORECASE)) >= 6


def _append_schedule_phase_spec_notes(
    bundle: dict,
    *,
    prefers_chinese: bool,
    task: str,
    display_language: str = "",
) -> None:
    if not _is_schedule_phase_task(task):
        return
    if prefers_chinese:
        bundle["spec"]["markdown"] = f"""# Task
围绕这条 weekly digest 定时发送任务交付可证明的 schedule timezone recurrence 闭环：{task}

# Done When
- Schedule Contract Inspector 只读固定 timezone source、user timezone fallback、本地周一 09:00、DST spring-forward/fall-back 样本、missed-run catch-up window、retry/provider replay idempotency key、subscription/disabled/tenant/locale filters、provider delivery/failure surface、scheduled_at/due_at/sent_at/skipped_reason/timezone_version/job_run_id audit fields、monitoring、migration 和 local governance proof targets。
- Digest Scheduler Builder 只基于 contract handoff 实现调度、发送、补偿、幂等、过滤、审计和监控证据。
- Temporal Correctness Inspector 与 Delivery Audit Inspector 并行读取同一个 contract 与 builder handoff，并分别留下 Proven、Weak、Unproven、Blocking 或 Residual risk 判断。
- Schedule GateKeeper 只有在 timezone/DST、catch-up、idempotency、filtering、provider reconciliation、audit、monitoring、migration 和 local governance 证据都支持任务声明时才允许 finish。

# Guardrails
- 不扩展成普通 notification deliverability、usage quota reset、宽泛 queue platform 或只配置 cron。
- cron expression、本地触发一次、UTC-only、single-timezone-only、provider-accepted-only、缺少 DST boundary、缺少 catch-up/idempotency negative、缺少 unsubscribe/disabled negative、缺少 audit/monitoring、缺少 migration 或跳过本地治理都必须 fail closed。
- 不声称已观察到 scheduler、timezone library/database、queue/provider、subscription store、audit writer、monitoring 或 test runner，除非运行时在 workdir 中验证。
- 若 workdir 存在 AGENTS.md、design/README.md、design/ 或 tests/ 等本地治理入口，相关角色必须读取并验证适用义务。

# Success Surface
- 用户可以审计每个用户按 timezone 本地周一 09:00 发送的证明，包括 DST 前后、missed-run catch-up once、retry/provider replay 不重复发送。
- 用户可以审计 unsubscribe、disabled user、tenant 和 locale filters 的负向样本。
- 用户可以审计 provider accepted/delivered/failure 与本地 scheduled_at/due_at/sent_at/skipped_reason/timezone_version/job_run_id audit fields 的对账。
- 用户可以看到 monitoring alerts、migration/backward compatibility、local-governance proof，以及每条声明的 Proven、Weak、Unproven、Blocking 或 Residual risk。

# Fake Done
- cron-only、local-trigger-only、UTC-only、single-timezone-only、provider-accepted-only 不得通过。
- 缺少 DST boundary、catch-up/idempotency negative、unsubscribe/disabled negative、provider reconciliation、audit fields、monitoring alerts、migration compatibility 或 local governance proof 时不得通过。

# Evidence Preferences
- 优先 multi-timezone fixtures、DST spring-forward/fall-back boundary cases、missed-run catch-up artifacts、retry/provider replay duplicate negatives、timezone database/version drift proof。
- 优先 unsubscribe/disabled/tenant/locale negatives、provider delivery/failure reconciliation、audit field samples、monitoring alerts、migration compatibility 和 local-governance evidence。
- GateKeeper verdict 必须引用上游 handoff、evidence refs 或 artifact，而不是只读最终总结。

# Execution Strategy
采用 Schedule Contract Inspector -> Digest Scheduler Builder -> [Temporal Correctness Inspector + Delivery Audit Inspector] -> Schedule GateKeeper。两个 Inspector 使用同一个 parallel_group，读取同一个 contract 与 builder handoff；GateKeeper 汇总所有 handoff 和 evidence_query 后裁决。

# Judgment Tradeoffs
时间语义、DST/catch-up 正确性、重复发送反证、退订/禁用保护、审计和监控证据优先于快速配置 cron。速度不能覆盖 UTC-only、single-timezone-only 或 provider-accepted-only。

# Residual Risk
轻微 digest copy、额外 locale coverage 或非关键 provider sample 可以作为 Residual risk 留下，但必须点名 owner/follow-up。缺少 timezone/DST、catch-up、idempotency、filter negatives、provider reconciliation、audit、monitoring、migration 或 local governance 证据必须 fail closed。

# Role Notes
## Schedule Contract Inspector Notes
只读固定时间语义、DST/catch-up 样本、idempotency/filter/audit/monitoring/migration proof targets；不实现代码。

## Digest Scheduler Builder Notes
只基于 contract handoff 实现最小调度闭环，并留下改动面、fixtures、命令输出或 artifact refs。

## Temporal Correctness Inspector Notes
反证 cron-only、UTC-only、single-timezone-only、本地触发一次、DST boundary 缺失、catch-up 漏补/多补和 replay duplicate。

## Delivery Audit Inspector Notes
验证 unsubscribe/disabled/tenant/locale negatives、provider reconciliation、audit fields、monitoring、migration 和 governance。

## Schedule GateKeeper Notes
从 contract、builder、两个并行 inspection handoff 和 evidence_query 裁决；核心 schedule 声明未 Proven 时 fail closed。
"""
        return
    if str(display_language or "").strip().lower() == "es":
        bundle["spec"]["markdown"] = f"""# Task
Gobernar un cierre probado de weekly digest schedule / timezone recurrence: {task}

# Done When
- Schedule Contract Inspector fija timezone source, fallback, local Monday 09:00, DST, catch-up, retry/provider replay, filters, provider delivery/failure, audit fields, monitoring, migration y governance targets.
- Digest Scheduler Builder implementa solo desde ese handoff.
- Temporal Correctness Inspector y Delivery Audit Inspector inspeccionan en paralelo el mismo contract y builder handoff.
- Schedule GateKeeper termina solo cuando timezone/DST, catch-up, idempotency, filtering, provider reconciliation, audit, monitoring, migration y governance son Proven.

# Guardrails
- No convertirlo en notification genérica, quota reset, queue platform amplia o solo cron.
- Cron-only, local-trigger-only, UTC-only, single-timezone-only, provider-accepted-only, missing DST, catch-up/idempotency, subscription negatives, audit/monitoring, migration o governance deben fail closed.
- No afirmar stack o runner sin verificar en workdir.

# Success Surface
- Evidencia auditables para local Monday 09:00 por timezone, DST, catch-up once, replay sin duplicados, filtros, provider reconciliation, audit fields, monitoring, migration y governance.
- Cada claim se clasifica como Proven, Weak, Unproven, Blocking o Residual risk.

# Fake Done
- Cron expression, un trigger local, UTC-only, single-timezone-only o provider accepted no pasan.

# Evidence Preferences
- Preferir fixtures multi-timezone, DST, catch-up, replay negatives, timezone version drift, filter negatives, provider reconciliation, audit samples, alerts, migration y governance.

# Execution Strategy
Schedule Contract Inspector -> Digest Scheduler Builder -> [Temporal Correctness Inspector + Delivery Audit Inspector] -> Schedule GateKeeper con parallel_group explícito.

# Judgment Tradeoffs
Semántica temporal, DST/catch-up, duplicate negatives, filtering, audit y monitoring pesan más que configurar cron rápido.

# Residual Risk
Solo riesgos menores con owner/follow-up; faltas centrales fail closed.

# Role Notes
## Schedule Contract Inspector Notes
Fija contrato y targets; no implementa.

## Digest Scheduler Builder Notes
Implementa solo el cierre mínimo desde handoff y deja evidencia.

## Temporal Correctness Inspector Notes
Refuta cron-only, UTC-only, single-timezone-only, DST/catch-up gaps y replay duplicates.

## Delivery Audit Inspector Notes
Verifica filtros, provider reconciliation, audit, monitoring, migration y governance.

## Schedule GateKeeper Notes
Decide desde todos los handoffs y evidence_query; fail closed si claims centrales no son Proven.
"""
        return
    bundle["spec"]["markdown"] = f"""# Task
Deliver a proven weekly digest schedule / timezone recurrence loop: {task}

# Done When
- Schedule Contract Inspector read-only freezes timezone source, user timezone fallback, local Monday 09:00 semantics, DST spring-forward/fall-back samples, missed-run catch-up window, retry/provider replay idempotency key, subscription/disabled/tenant/locale filters, provider delivery/failure surface, audit fields, monitoring, migration, and local-governance proof targets.
- Digest Scheduler Builder implements scheduling, delivery, catch-up, idempotency, filtering, audit, and monitoring evidence only from that handoff.
- Temporal Correctness Inspector and Delivery Audit Inspector inspect the same contract plus builder handoffs in parallel and classify findings as Proven, Weak, Unproven, Blocking, or Residual risk.
- Schedule GateKeeper finishes only when timezone/DST, catch-up, idempotency, filtering, provider reconciliation, audit, monitoring, migration, and local governance evidence prove the task claims.

# Guardrails
- Do not expand into generic notification deliverability, usage quota reset, broad queue-platform work, or cron configuration only.
- Cron-expression-only, local-trigger-only, UTC-only, single-timezone-only, provider-accepted-only, missing DST boundary, missing catch-up/idempotency negative, missing unsubscribe/disabled negative, missing audit/monitoring, missing migration, or skipped local governance must fail closed.
- Do not claim the scheduler, timezone library/database, queue/provider, subscription store, audit writer, monitoring, or test runner was observed unless verified in the workdir.

# Success Surface
- Users can audit local Monday 09:00 delivery per timezone, DST boundary behavior, missed-run catch-up once, and retry/provider replay without duplicates.
- Users can audit unsubscribe, disabled-user, tenant, and locale negative cases.
- Users can reconcile provider accepted/delivered/failure events with scheduled_at, due_at, sent_at, skipped_reason, timezone_version, and job_run_id audit fields.
- Users can see monitoring alerts, migration/backward compatibility, local-governance proof, and each claim's evidence bucket.

# Fake Done
- Cron-only, local-trigger-only, UTC-only, single-timezone-only, and provider-accepted-only evidence do not pass.
- Missing DST boundary, catch-up/idempotency negative, unsubscribe/disabled negative, provider reconciliation, audit fields, monitoring alerts, migration compatibility, or local-governance proof does not pass.

# Evidence Preferences
- Prefer multi-timezone fixtures, DST spring-forward/fall-back boundary cases, missed-run catch-up artifacts, retry/provider replay duplicate negatives, and timezone database/version drift proof.
- Prefer unsubscribe/disabled/tenant/locale negatives, provider delivery/failure reconciliation, audit field samples, monitoring alerts, migration compatibility, and local-governance evidence.
- GateKeeper verdict must cite upstream handoffs, evidence refs, or artifacts, not only a final narrative.

# Execution Strategy
Use Schedule Contract Inspector -> Digest Scheduler Builder -> [Temporal Correctness Inspector + Delivery Audit Inspector] -> Schedule GateKeeper. Both Inspectors share one parallel_group and read the same contract plus builder handoffs; GateKeeper combines all handoffs and evidence_query before judgment.

# Judgment Tradeoffs
Time semantics, DST/catch-up correctness, duplicate-send negatives, unsubscribe/disabled protection, audit, and monitoring proof beat fast cron setup. Speed cannot hide UTC-only, single-timezone-only, or provider-accepted-only proof.

# Residual Risk
Minor digest copy, extra locale coverage, or non-critical provider samples may remain only with owner/follow-up. Missing timezone/DST, catch-up, idempotency, filter negatives, provider reconciliation, audit, monitoring, migration, or local governance evidence must fail closed.

# Role Notes
## Schedule Contract Inspector Notes
Freeze time semantics, DST/catch-up samples, idempotency/filter/audit/monitoring/migration proof targets; do not implement.

## Digest Scheduler Builder Notes
Implement the smallest scheduling loop from the contract handoff and leave changed surfaces, fixtures, command output, or artifact refs.

## Temporal Correctness Inspector Notes
Refute cron-only, UTC-only, single-timezone-only, local-trigger-only, missing DST boundary, catch-up gaps, and replay duplicates.

## Delivery Audit Inspector Notes
Verify unsubscribe/disabled/tenant/locale negatives, provider reconciliation, audit fields, monitoring, migration, and governance.

## Schedule GateKeeper Notes
Judge from contract, builder, both parallel inspection handoffs, and evidence_query; fail closed unless core schedule claims are Proven.
"""


def _is_schedule_phase_task(task: str) -> bool:
    text = str(task or "")
    if re.search(
        r"usage\s+meter(?:ing|ed)?|usage\s+event|quota\s+(?:enforcement|limit|window)|plan\s+(?:quota|limit)|api\s+usage|usage\s+ledger|额度|配额|限额",
        text,
        re.IGNORECASE,
    ) and re.search(
        r"concurrent|duplicate|idempot|plan\s+upgrade|plan\s+downgrade|billing\s+period|grace\s+limit|hard\s+limit|over[- ]?limit|invoice|subscription\s+provider|并发|重复|幂等|套餐|计费周期|宽限|硬限制|超限|发票|订阅",
        text,
        re.IGNORECASE,
    ):
        return False
    if not re.search(r"weekly\s+digest|digest|schedule|scheduler|cron|timezone|DST|定时|周一|夏令时", text, re.IGNORECASE):
        return False
    phase_markers = (
        r"timezone|时区",
        r"\bDST\b|daylight|夏令时",
        r"missed[- ]?run|catch[- ]?up|错过执行|补偿|补一次",
        r"retry|provider\s+replay|duplicate|idempotenc|重试|重复|幂等",
        r"subscription|unsubscribe|disabled|tenant|locale|退订|禁用|租户",
        r"audit|scheduled_at|due_at|sent_at|skipped_reason|job_run_id|审计",
        r"monitoring|alert|drift|backlog|provider\s+failure|监控|告警|漂移|积压",
        r"cron[- ]?only|local[- ]?trigger|UTC[- ]?only|single[- ]?timezone|本地触发|只测|一个时区",
    )
    return sum(1 for pattern in phase_markers if re.search(pattern, text, re.IGNORECASE)) >= 4


