def _append_concurrency_conflict_resolution_spec_notes(
    bundle: dict,
    *,
    prefers_chinese: bool,
    task: str,
    display_language: str = "",
) -> None:
    if not _is_concurrency_conflict_resolution_task(task):
        return
    markdown = str(bundle.get("spec", {}).get("markdown") or "")
    if "# Collaborative Conflict Resolution Workflow Notes" in markdown:
        return
    if prefers_chinese:
        notes = f"""# Task
围绕这条用户任务锚点治理 collaborative document editing conflict resolution：{task}

# Done When
- Conflict Contract Inspector 只读固定 two-user same-paragraph edit fixtures、version conflict / optimistic-lock semantics、safe merge versus reject rules、offline edit queue replay、idempotency keys、permission matrix、lower-permission overwrite negatives、audit fields、monitoring 和 local governance proof targets。
- Collaboration Builder 读取 contract handoff 后才实现，并留下 version checks、conflict prompt / safe merge、offline replay、permission enforcement、audit 和 monitoring 的改动面、fixtures、命令输出或 artifact refs。
- Conflict Evidence Inspector 与 Permission Audit Inspector 使用同一个 parallel_group 并行读取 contract 与 builder handoff；Conflict Evidence 验证 concurrent edit lost-update prevention、version conflict UI/API response、safe merge 或 both-sides-preserved、offline replay idempotency、retry handling 和 last-write-wins negative proof；Permission Audit 验证 unauthorized overwrite rejection、permission downgrade/revocation、audit logs、base_version/resolved_by/merge outcome、replay audit、monitoring 和 governance。
- GateKeeper 读取所有 handoff，并从 evidence_query 裁决 conflict-resolution、idempotency、permission-auth、audit-log、monitoring、negative_evidence 和 local-governance；single-user-save-only、last-write-wins、happy-path WebSocket-only、optimistic-lock proof 缺失、offline replay idempotency 缺失、both-sides-preserved proof 缺失、permission negative 缺失、audit 缺失或本地治理跳过必须 fail closed。

# Guardrails
- 不把单人保存成功、最后写入 wins、WebSocket happy path 或两个客户端都显示更新当成完成。
- 不把库存/usage 并发、通用权限重写或编辑器 UI polish 当成协作文档冲突解决证明。
- 不声称已观察到协作编辑栈、版本模型、offline queue、permission model、audit、monitoring 或 test runner，除非运行时在 workdir 中验证。
- 若 workdir 存在 AGENTS.md、design/README.md、design/ 或 tests/ 等项目本地治理入口，Builder 必须读取适用规则，两个 Inspector 必须验证相关 design/test/access/audit/monitoring 义务，GateKeeper 必须把跳过本地治理视为 Weak、Unproven 或 Blocking。

# Success Surface
- 两个用户同时编辑同一段不会 silent overwrite，且 last-write-wins 有负向反证。
- version conflict / optimistic locking 会产生可审计的冲突提示、safe merge 或 reject。
- 离线编辑恢复后的 replay 幂等，retry/replay 不重复覆盖。
- 冲突解决保留两边内容，低权限或权限撤销用户不能覆盖别人改动。
- audit log 覆盖 base_version、resolved_by、merge outcome、retry/replay 和 permission denial。

# Fake Done
- single-user-save-only、last-write-wins、happy-path WebSocket-only、optimistic-lock proof 缺失、offline replay idempotency 缺失、both-sides-preserved proof 缺失、permission negative 缺失、audit 缺失或 monitoring 缺失不得通过。

# Evidence Preferences
- 优先 two-user same-paragraph fixtures、lost-update negative、version conflict UI/API response、optimistic-lock checks、safe merge/reject artifacts、both-sides-preserved evidence、offline replay idempotency、retry/replay proof、permission matrix negatives、audit refs、monitoring alerts 和 local-governance evidence。
- 每条 conflict-resolution claim 必须进入 Proven、Weak、Unproven、Blocking 或 Residual risk。

# Residual Risk
- 轻微 editor UI polish、额外冲突样本或非关键 collaboration presence 可作为 Residual risk 留下，但必须有 owner、follow-up 和 acceptance path。
- 缺少 lost-update prevention、optimistic locking、offline replay、both-sides-preserved、permission negative、audit、monitoring 或 local-governance evidence 必须 fail closed。

# Collaborative Conflict Resolution Workflow Notes
- 这条 Loop 使用 Conflict Contract Inspector -> Collaboration Builder -> [Conflict Evidence Inspector + Permission Audit Inspector] -> Conflict Resolution GateKeeper，并且两个 Inspector 在同一个有界 parallel_group 中并行检查。
"""
    elif str(display_language or "").strip().lower() == "es":
        notes = f"""# Task
Gobernar collaborative document editing conflict resolution para esta ancla: {task}

# Done When
- Conflict Contract Inspector fija two-user fixtures, optimistic locking, safe merge/reject, offline replay, idempotency keys, permission matrix, audit, monitoring y governance.
- Collaboration Builder implementa desde ese handoff.
- Conflict Evidence Inspector y Permission Audit Inspector leen contract y builder handoffs en el mismo parallel_group.
- GateKeeper decide conflict-resolution, idempotency, permission-auth, audit-log, monitoring, negative_evidence y local-governance; shallow proof fail closed.

# Collaborative Conflict Resolution Workflow Notes
- Conflict Evidence verifica lost-update prevention, conflict UI/API response, both-sides-preserved, offline replay idempotency y last-write-wins negatives.
- Permission Audit verifica unauthorized overwrite, permission changes, audit logs, replay audit, monitoring y governance.
"""
    else:
        notes = f"""# Task
Govern collaborative document editing conflict resolution for this user task anchor: {task}

# Done When
- Conflict Contract Inspector read-only freezes two-user same-paragraph edit fixtures, version conflict / optimistic-lock semantics, safe merge versus reject rules, offline edit queue replay, idempotency keys, permission matrix, lower-permission overwrite negatives, audit fields, monitoring, and local-governance proof targets.
- Collaboration Builder reads the contract handoff before implementation, then leaves changed surfaces, fixtures, command output, or artifact refs for version checks, conflict prompt / safe merge, offline replay, permission enforcement, audit, and monitoring.
- Conflict Evidence Inspector and Permission Audit Inspector read contract plus builder handoffs in the same parallel_group; Conflict Evidence verifies concurrent edit lost-update prevention, version conflict UI/API response, safe merge or both-sides-preserved behavior, offline replay idempotency, retry handling, and last-write-wins negative proof; Permission Audit verifies unauthorized overwrite rejection, permission downgrade/revocation, audit logs, base_version/resolved_by/merge outcome, replay audit, monitoring, and governance.
- GateKeeper reads all handoffs and judges conflict-resolution, idempotency, permission-auth, audit-log, monitoring, negative_evidence, and local-governance through evidence_query; single-user-save-only, last-write-wins, happy-path WebSocket-only, missing optimistic-lock proof, missing offline replay idempotency, missing both-sides-preserved proof, missing permission negative, missing audit, or skipped local governance must fail closed.

# Guardrails
- Do not treat single-user save, last-write-wins, a happy-path WebSocket update, or two clients showing updates as completion.
- Do not substitute inventory/usage concurrency, broad permission rewrites, or editor UI polish for collaborative document conflict-resolution proof.
- Do not claim the collaboration stack, version model, offline queue, permission model, audit, monitoring, or test runner has been observed unless the run verifies it in the workdir.
- If project-local governance markers such as AGENTS.md, design/README.md, design/, or tests/ exist, Builder must read applicable rules, both Inspectors must verify related design/test/access/audit/monitoring obligations, and GateKeeper must treat skipped local governance as Weak, Unproven, or Blocking.

# Success Surface
- Two users editing the same paragraph do not silently overwrite each other, and last-write-wins has negative proof.
- Version conflict / optimistic locking produces an auditable conflict prompt, safe merge, or reject.
- Offline edits replay idempotently after reconnect, and retry/replay does not duplicate overwrites.
- Conflict resolution preserves both sides, and lower-permission or revoked users cannot overwrite someone else.
- Audit logs cover base_version, resolved_by, merge outcome, retry/replay, and permission denial.

# Fake Done
- single-user-save-only, last-write-wins, happy-path WebSocket-only, missing optimistic-lock proof, missing offline replay idempotency, missing both-sides-preserved proof, missing permission negative, missing audit, or missing monitoring cannot pass.

# Evidence Preferences
- Prefer two-user same-paragraph fixtures, lost-update negatives, version conflict UI/API response, optimistic-lock checks, safe merge/reject artifacts, both-sides-preserved evidence, offline replay idempotency, retry/replay proof, permission matrix negatives, audit refs, monitoring alerts, and local-governance evidence.
- Each conflict-resolution claim must be classified as Proven, Weak, Unproven, Blocking, or Residual risk.

# Residual Risk
- Minor editor UI polish, extra conflict fixture coverage, or non-critical collaboration presence may remain only with an owner, follow-up, and acceptance path.
- Missing lost-update prevention, optimistic locking, offline replay, both-sides-preserved, permission negative, audit, monitoring, or local-governance evidence must fail closed.

# Collaborative Conflict Resolution Workflow Notes
- This Loop uses Conflict Contract Inspector -> Collaboration Builder -> [Conflict Evidence Inspector + Permission Audit Inspector] -> Conflict Resolution GateKeeper with one bounded parallel inspection group.
"""
    bundle["spec"]["markdown"] = notes.rstrip()


